<script setup lang="ts">
const api=useApi(),notice=useNotice(),data=ref<any>(null),error=ref(''),busy=ref(false),page=ref(1)
const drafts=reactive<Record<string,any>>({})
const pages=computed(()=>Math.max(1,Math.ceil(Math.max(data.value?.counts.members||0,data.value?.counts.requests||0)/50)))
async function load(){error.value='';try{data.value=await api('/api/admin/platform',{query:{page:page.value}});for(const p of data.value.plans){drafts[p.code]={...p,monthly:p.monthly_price_minor==null?'':(p.monthly_price_minor/100).toFixed(2),annual:p.annual_price_minor==null?'':(p.annual_price_minor/100).toFixed(2)}}}catch(e){error.value=errorMessage(e)}}
onMounted(load)
function cents(value:string){const text=String(value).trim();if(!text)return null;if(!/^\d+(?:\.\d{1,2})?$/.test(text))throw new Error('Enter a positive AUD amount with at most two decimal places.');const [whole,fraction='']=text.split('.');return Number(whole)*100+Number(fraction.padEnd(2,'0'))}
async function savePlan(code:string){if(busy.value)return;busy.value=true;try{const p=drafts[code];await api('/api/admin/platform/plans/'+code,{method:'PUT',body:{name:p.name,description:p.description,monthly_price_minor:cents(p.monthly),annual_price_minor:cents(p.annual),revision:p.revision}});notice.show('Draft saved. No access or billing changes.');await load()}catch(e){notice.show(errorMessage(e),'error')}finally{busy.value=false}}
async function status(request:any,next:string){if(busy.value)return;busy.value=true;try{await api('/api/admin/platform/requests/'+request.id,{method:'PATCH',body:{status:next,revision:request.revision}});await load()}catch(e){notice.show(errorMessage(e),'error')}finally{busy.value=false}}
async function remove(request:any){if(busy.value||!confirm('Delete this request and its contact details? This does not delete a user account.'))return;busy.value=true;try{await api('/api/admin/platform/requests/'+request.id,{method:'DELETE',body:{revision:request.revision}});await load()}catch(e){notice.show(errorMessage(e),'error')}finally{busy.value=false}}
async function changePage(next:number){page.value=next;await load()}
useSeoMeta({title:'Platform administration · CardShelf'})
</script>
<template><NuxtLink to="/account" class="text-button back-link"><AppIcon name="left" :size="16" />Your account</NuxtLink><header class="page-heading"><div><span class="eyebrow">PLATFORM ADMINISTRATION</span><h1>People, access & future plans.</h1><p>Build the platform without interrupting your testers.</p></div><button class="button secondary" :disabled="busy" @click="load"><AppIcon name="refresh" :size="17" />Refresh</button></header><p class="alert info"><AppIcon name="shield" />Billing and access enforcement are disabled. Existing testers keep their non-expiring access. Plan drafts do not charge or restrict anyone.</p><p v-if="error" class="alert error">{{error}}</p><p v-if="!data&&!error" class="loading-panel">Loading platform information…</p><template v-if="data"><section class="panel platform-admin-panel"><div class="section-heading"><div><h2>Requests to review</h2><p>Access, support and privacy requests from the website. No emails are sent automatically.</p></div><span class="badge purple">{{data.counts.new_requests}} new</span></div><article v-for="request in data.requests" :key="request.id" class="platform-request"><div class="request-header"><div><strong>{{request.name}}</strong><p class="small muted">{{request.email}} · {{request.purpose.replace('_',' ')}}</p></div><span class="badge" :class="request.status==='new'?'purple':''">{{request.status}}</span></div><p>{{request.message||'No additional message.'}}</p><div class="button-row"><button class="button secondary small-button" :disabled="busy||request.status==='contacted'" @click="status(request,'contacted')">Mark contacted</button><button class="button secondary small-button" :disabled="busy||request.status==='archived'" @click="status(request,'archived')">Archive</button><button class="text-button danger-text" :disabled="busy" @click="remove(request)">Delete contact request</button></div></article><p v-if="!data.requests.length" class="platform-admin-empty">No requests on this page.</p><p class="data-note">To invite a tester, create their account using Add a collector in Data & settings and share their initial password securely. Marking a request contacted does not create an account.</p><NuxtLink to="/settings" class="text-button">Create a tester in settings<AppIcon name="arrow" :size="16" /></NuxtLink></section><section class="panel platform-admin-panel spaced"><h2>Tester accounts</h2><p class="small muted">These records are informational. There is no revoke-access or enable-billing control in this release.</p><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Access</th><th>Expiry</th></tr></thead><tbody><tr v-for="member in data.members" :key="member.id"><td>{{member.name}}</td><td>{{member.email}}</td><td>{{member.role}}</td><td><span class="badge green">{{member.grant_kind==='legacy_tester'?'Existing tester':'Beta tester'}}</span></td><td>No automatic expiry</td></tr></tbody></table></div></section><div class="platform-pagination"><button class="button secondary" :disabled="page<=1||busy" @click="changePage(page-1)">Previous</button><span>Page {{page}} of {{pages}} · up to 50 requests and members per page</span><button class="button secondary" :disabled="page>=pages||busy" @click="changePage(page+1)">Next</button></div><section><h2>Future subscription drafts</h2><p class="muted small">Optional planning figures in AUD. Leave prices blank until decided. These drafts are not shown on the public plans page, assigned to testers or connected to a payment provider.</p><div class="platform-admin-plans"><form v-for="plan in data.plans.filter((p:any)=>p.state==='draft')" :key="plan.code" class="panel platform-admin-panel form-stack" @submit.prevent="savePlan(plan.code)"><span class="badge">{{plan.code}} · unpublished draft</span><label>Plan name<input v-model="drafts[plan.code].name" required maxlength="80" /></label><label>Description<textarea v-model="drafts[plan.code].description" maxlength="500" /></label><div class="form-columns"><label>Monthly price · AUD<input v-model="drafts[plan.code].monthly" inputmode="decimal" placeholder="Not decided" /></label><label>Annual price · AUD<input v-model="drafts[plan.code].annual" inputmode="decimal" placeholder="Not decided" /></label></div><button class="button secondary" :disabled="busy">Save draft only</button></form></div></section></template></template>
